/* 本文件只服务于独立设计评审，不接入项目业务、推理或工单接口。 */
'use strict';
const $ = selector => document.querySelector(selector);
const escapeHtml = value => String(value == null ? '' : value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<i data-lucide="${name}" aria-hidden="true"></i>`;
const activateIcons = () => lucide.createIcons({attrs:{'stroke-width':1.7}});
const formatTime = value => new Date(value).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const fullTime = value => new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});
const scenes = [
  {id:'A01/gate',device:'A01',check:'闸机运行状态',title:'闸机运行异常',point:'闸机',node:2,file:'gate-running-status.jpg',description:'巡检记录提示闸机运行异常，请到达检查点核查设备运行状态。',default:true},
  {id:'A01/tvm',device:'A01',check:'TVM购票机状态',title:'TVM购票机状态异常',point:'TVM购票机',node:5,file:'tvm-status.jpg'},
  {id:'A01/light',device:'A01',check:'照明灯亮度识别',title:'照明灯亮度异常',point:'照明灯',node:6,file:'lighting-brightness.png'},
  {id:'A01/escalator',device:'A01',check:'电扶梯运行状态',title:'电扶梯运行异常（A01 检查点）',point:'电扶梯',node:8,file:'escalator-a02.jpg'},
  {id:'A01/rolling-door',device:'A01',check:'卷帘门开/关是否正常',title:'卷帘门开关异常',point:'卷帘门',node:17,file:'rolling-door-status.png'},
  {id:'A02/trash',device:'A02',check:'垃圾桶满溢乱放',title:'垃圾桶满溢或摆放异常',point:'垃圾桶',node:2,file:'trash-overflow.jpg',description:'巡检记录提示垃圾桶满溢或摆放异常，请到达检查点核查桶内情况与摆放位置。',default:true},
  {id:'A02/hydrant-door',device:'A02',check:'消火栓门状态识别',title:'消火栓门状态异常',point:'消火栓',node:3,file:'hydrant-door.jpg',description:'巡检记录提示消火栓门状态异常，请到达检查点核查箱门及周边情况。',default:true},
  {id:'A02/fight',device:'A02',check:'人员打架识别',title:'发现人员打架',point:'人员打架',node:5,file:'passenger-fight.jpg'},
  {id:'A02/emergency-light',device:'A02',check:'应急指示灯状态',title:'应急指示灯状态异常',point:'应急指示灯',node:6,file:'emergency-exit-sign.jpg'},
  {id:'A02/comatose',device:'A02',check:'人员躺卧/昏迷识别',title:'发现人员躺卧或疑似昏迷',point:'人员躺卧',node:8,file:'passenger-lying.jpg'},
  {id:'A02/flood-supply',device:'A02',check:'防汛物资状态',title:'防汛物资状态异常',point:'防汛物资',node:9,file:'flood-supplies.jpg'},
  {id:'A02/escalator',device:'A02',check:'电扶梯状态',title:'电扶梯状态异常（A02 检查点）',point:'电扶梯',node:10,file:'escalator-a01.jpg'}
].map(scene=>({...scene,location:`云谷路地铁站 · ${scene.device} ${scene.point}检查点`,description:scene.description||`巡检记录提示${scene.title}，请到达对应检查点进行现场核查。`}));
const results = [
  {id:'handled',name:'已处理',icon:'circle-check',intro:'问题已处理，填写处理情况并提供处理后照片。',label:'处理说明',hint:'请填写现场处理情况',photo:'处理后照片'},
  {id:'normal',name:'核查无异常',icon:'shield-check',intro:'现场核查未发现异常，填写核查情况并提供现场照片。',label:'核查说明',hint:'请填写现场核查情况',photo:'现场照片'},
  {id:'parts',name:'需配件支持',icon:'wrench',intro:'需要配件支持，填写所需配件类型。',label:'配件类型',hint:'请填写所需配件类型',photo:null}
];
const storageKey='station-workorder-design-v1-core';
const makeOrders=()=>['A02/trash','A02/hydrant-door','A01/gate'].map((id,index)=>({sceneId:id,number:`GD20261111${String(index+1).padStart(4,'0')}`,status:'pending',receivedAt:Date.now(),startedAt:null,completedAt:null,result:null,branches:{handled:{text:'',photos:[]},normal:{text:'',photos:[]},parts:{text:'',photos:[]}}}));
let orders=makeOrders(),tab='pending',page='list',selected=0,listScroll=0,epoch=0,busy=false,undoPhoto=null,mode='app';
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved&&saved.version===1&&Array.isArray(saved.orders)&&saved.orders.length===3){orders=saved.orders;tab=['pending','processing','done'].includes(saved.tab)?saved.tab:'pending';listScroll=saved.listScroll||0}}catch{/* 存储不可用时保留当前浏览器会话，后续保存明确反馈。 */}
const order=()=>orders[selected];
const scene=()=>scenes.find(item=>item.id===order().sceneId);
const result=()=>results.find(item=>item.id===order().result);
const branch=()=>order().branches[order().result];
const hasDraft=item=>Boolean(item.result||Object.values(item.branches).some(value=>value.text||value.photos.length));
const statusName=value=>({pending:'待处理',processing:'处理中',done:'已完成'}[value]);
const badge=value=>`<span class="badge ${value==='processing'?'processing':value==='done'?'done':''}">${statusName(value)}</span>`;
function save(){try{localStorage.setItem(storageKey,JSON.stringify({version:1,orders,tab,listScroll}));return true}catch{toast('本机保存失败，请保留当前页面并重试');return false}}
function toast(message){const target=$('#app-toast');target.textContent=message;target.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>target.hidden=true,2600)}
function header(title){return `<header class="app-header"><button class="icon-button" data-action="back" aria-label="返回">${icon('chevron-left')}</button><h1>${title}</h1></header>`}
function locationMarkup(item,cls=''){return `<div class="location ${cls}">${icon('map-pin')}<span>${escapeHtml(item.location)}</span></div>`}
function summary(){const item=scene();return `<section class="section-card compact-summary"><h2>${escapeHtml(item.title)}</h2>${locationMarkup(item)}</section>`}
function footer(text,action,tip=''){return `<footer class="action-footer">${tip?`<p class="footer-tip">${tip}</p>`:''}<button class="primary" data-action="${action}" ${busy?'disabled':''}>${text}${icon(action==='submit'?'check':'arrow-right')}</button></footer>`}
function listMarkup(){const shown=orders.map((item,index)=>({item,index})).filter(({item})=>item.status===tab);return `<header class="app-header list-header"><div><p class="app-name">智慧车站</p><h1>我的工单</h1></div><div class="identity"><span class="avatar" aria-hidden="true">李</span><span>李明</span></div></header><nav class="tabs" role="tablist" aria-label="工单状态">${['pending','processing','done'].map(value=>`<button role="tab" data-tab="${value}" aria-selected="${tab===value}">${statusName(value)}<span class="count">${orders.filter(item=>item.status===value).length}</span></button>`).join('')}</nav><div class="app-scroll" id="scroll-area"><div class="list-context">${icon('map-pin')}云谷路地铁站</div>${shown.length?shown.map(({item,index})=>{const source=scenes.find(value=>value.id===item.sceneId);return `<button class="work-card" data-order="${index}"><div class="card-top"><span class="source-label">${icon('scan-line')}${source.device} 巡检</span>${badge(item.status)}</div><h2>${source.title}</h2>${locationMarkup(source)}${item.status==='processing'&&hasDraft(item)?'<p class="draft-mark">有未提交材料</p>':''}<div class="card-meta"><span>${formatTime(item.receivedAt)}</span><span>${item.number}</span></div></button>`}).join(''):`<div class="empty"><div class="empty-icon">${icon('clipboard-list')}</div><strong>暂无${statusName(tab)}工单</strong><p>${tab==='pending'?'新工单到达后将显示在这里':tab==='processing'?'开始处理后可在这里继续':'完成记录将保存在这里'}</p></div>`}</div>`}
function evidenceMarkup(){const item=scene();return `<section class="section-card"><h3>原始证据</h3><button class="evidence-button" data-action="evidence" aria-label="查看完整原始证据"><img src="assets/${item.file}" alt="${item.check}原始检查照片"><span>${icon('expand')}查看原图</span></button><p class="evidence-caption">巡检机器狗 ${item.device} · 原始检查照片</p></section>`}
function detailMarkup(){const item=scene(),current=order();return `${header('工单详情')}<div class="app-scroll" id="scroll-area"><section class="section-card"><div class="card-top">${badge(current.status)}<span class="source-label">${item.device} 巡检</span></div><h2>${item.title}</h2>${locationMarkup(item,'detail-location')}</section><section class="section-card"><h3>问题说明</h3><p class="body-copy">${item.description}</p></section>${evidenceMarkup()}<section class="section-card"><h3>工单信息</h3><dl class="facts"><dt>工单编号</dt><dd>${current.number}</dd><dt>接收时间</dt><dd>${formatTime(current.receivedAt)}</dd><dt>处理人</dt><dd>李明</dd>${current.startedAt?`<dt>开始时间</dt><dd>${formatTime(current.startedAt)}</dd>`:''}</dl></section>${current.startedAt?`<section class="section-card"><h3>处理记录</h3><div class="flow-record">李明开始处理<span>${fullTime(current.startedAt)}</span></div></section>`:''}</div>${footer(current.status==='pending'?'开始处理':hasDraft(current)?'继续填写':'填写结果',current.status==='pending'?'start':'write',current.status==='pending'?'到达现场后再开始':'')}`}
function resultMarkup(){return `${header('选择现场结果')}<div class="app-scroll" id="scroll-area">${summary()}<p class="result-intro">请根据现场情况选择一项结果。</p>${results.map(item=>`<button class="result-option" data-result="${item.id}"><span class="result-symbol">${icon(item.icon)}</span><span class="result-text"><strong>${item.name}</strong><span>${item.intro}</span></span>${icon('chevron-right')}</button>`).join('')}</div>`}
function photosMarkup(){const current=branch();return current.photos.map((photo,index)=>`<div class="photo-row"><button class="photo-thumb" data-photo="${index}" aria-label="查看第 ${index+1} 张照片"><img src="${photo.data}" alt="${result().photo} ${index+1}"></button><div class="photo-info">照片 ${index+1} · ${photo.source}<span class="upload-state">${photo.status}</span></div><button class="remove-photo" data-remove="${index}" ${busy?'disabled':''}>移除</button></div>`).join('')}
function formMarkup(){const current=result();return `${header('填写材料')}<div class="app-scroll" id="scroll-area">${summary()}<div class="result-current"><strong>${current.name}</strong><button class="text-action" data-action="change-result" ${busy?'disabled':''}>更换结果</button></div><section class="section-card"><label class="field-label" for="material-input">${current.label}<span class="required">*</span></label><textarea id="material-input" placeholder="${current.hint}" ${busy?'disabled':''}>${escapeHtml(branch().text)}</textarea><div id="text-error" class="field-error" role="alert" hidden></div></section>${current.photo?`<section class="section-card"><h3>${current.photo}<span class="required">*</span></h3><p class="field-help">至少添加 1 张照片</p><div class="photo-buttons"><button class="secondary" data-action="camera" ${busy?'disabled':''}>${icon('camera')}拍照</button><button class="secondary" data-action="album" ${busy?'disabled':''}>${icon('image-plus')}从相册选择</button></div><div id="photo-list">${photosMarkup()}</div><div id="photo-error" class="field-error" role="alert" hidden></div><div id="undo-area">${undoPhoto?'<div class="undo-banner">已移除照片<button class="text-action" data-action="undo">撤销</button></div>':''}</div></section>`:''}<div class="form-submit" id="inline-submit" hidden><button class="primary" data-action="submit" ${busy?'disabled':''}>${busy?'正在提交…':'提交并完成'}</button></div></div>${footer(busy?'正在提交…':'提交并完成','submit')}`}
function completedMarkup(){const current=order(),chosen=result();return `${header('完成记录')}<div class="app-scroll" id="scroll-area"><div class="done-heading"><span class="done-mark">${icon('check')}</span><h2>工单已完成</h2><p>${chosen.id==='parts'?'已记录配件需求，仍需配件支持':'现场结果已保存'}</p></div>${summary()}<section class="section-card"><h3>现场结果</h3><span class="result-value">${chosen.name}</span><h3>${chosen.label}</h3><p class="body-copy">${escapeHtml(branch().text).replace(/\n/g,'<br>')}</p>${chosen.photo&&branch().photos.length?`<div style="margin-top:16px"><h3>${chosen.photo}</h3>${branch().photos.map((photo,index)=>`<div class="photo-row"><button class="photo-thumb" data-photo="${index}" aria-label="查看已提交照片 ${index+1}"><img src="${photo.data}" alt="已提交照片 ${index+1}"></button><div class="photo-info">照片 ${index+1} · ${photo.source}<span class="upload-state">上传成功</span></div></div>`).join('')}</div>`:''}</section><div class="acceptance">${icon('shield-check')}系统默认验收通过</div><section class="section-card"><h3>处理记录</h3><div class="flow-record">李明提交并完成<span>${fullTime(current.completedAt)}</span></div><div class="flow-record">李明开始处理<span>${fullTime(current.startedAt)}</span></div><dl class="facts"><dt>工单编号</dt><dd>${current.number}</dd></dl></section>${evidenceMarkup()}</div>${footer('返回工单列表','list')}`}
const pageNotes={
  list:['我的工单','问题与位置优先|完整展示问题和检查点，编号、时间退居卡片末行。','三种业务状态|默认待处理；切换分类可查看空态，返回保留原分类和位置。','按实际状态呈现|有未提交材料才出现提示，不添加额外底部导航。'],
  detail:['工单详情','先确认，再开始|问题、位置、说明和原始证据按阅读顺序排列。','底部主操作|按钮保持可达，正文独立滚动。开始处理后仍停留在本页。','保留上下文|原始证据与处理记录分开，照片完整查看，不裁成装饰横幅。'],
  result:['选择现场结果','一次只做一个选择|三个选项纵排，首次不预选，不增加额外确认步骤。','结果有明确含义|需配件支持表示仍待配件，不暗示现场问题已修复。','触控独立完成|整张选项卡可点击，无需实体键盘。'],
  form:['填写材料','必填与结果绑定|说明与照片各自就近校验；配件类只要求配件类型。','材料按分支保留|更换结果可回看之前材料，提交仅使用当前分支。','输入时可滚动|聚焦输入后提交区随表单滚动，收起后恢复底部主操作。'],
  complete:['完成记录','完成结果可追溯|显示已提交材料、处理人及时间，原始证据仍可查看。','配件类明确保留需求|工单完成与设备修复分别表达，不混淆。','流程在本单结束|只读查看并返回列表，不自动进入下一张工单。']
};
function render(keepScroll=false){const previous=$('#scroll-area')?.scrollTop||0;$('#app').classList.remove('form-focused');$('#app').innerHTML=({list:listMarkup,detail:detailMarkup,result:resultMarkup,form:formMarkup,complete:completedMarkup}[page])();const notes=pageNotes[page];$('#current-page').textContent=notes[0];$('#page-notes').innerHTML=notes.slice(1).map(note=>{const [title,body]=note.split('|');return `<p class="design-point"><strong>${title}</strong>${body}</p>`}).join('');activateIcons();const scroll=$('#scroll-area');scroll.scrollTop=page==='list'?listScroll:keepScroll?previous:0;if(page==='list')scroll.addEventListener('scroll',()=>{listScroll=scroll.scrollTop});}
function go(next){$('#app-toast').hidden=true;clearTimeout(toast.timer);if(page==='list'){listScroll=$('#scroll-area').scrollTop;save()}page=next;undoPhoto=null;render()}
function back(){if(busy)return;if(page==='detail'||page==='complete')go('list');else if(page==='result')go('detail');else if(page==='form')go('result')}
$('#app').addEventListener('click',event=>{
  const button=event.target.closest('button');if(!button||button.disabled)return;
  if(button.dataset.tab){tab=button.dataset.tab;listScroll=0;save();render();return}
  if(button.dataset.order!==undefined){selected=Number(button.dataset.order);go(order().status==='done'?'complete':'detail');return}
  if(button.dataset.result){order().result=button.dataset.result;save();go('form');return}
  if(button.dataset.photo!==undefined){openPhoto(branch().photos,Number(button.dataset.photo),false);return}
  if(button.dataset.remove!==undefined){const index=Number(button.dataset.remove);undoPhoto={photo:branch().photos.splice(index,1)[0],index,sceneId:order().sceneId,resultId:order().result};save();render(true);return}
  const action=button.dataset.action;
  if(action==='back')back();
  if(action==='list')go('list');
  if(action==='start'){const snapshot=JSON.stringify(order());order().status='processing';order().startedAt=Date.now();if(save()){render(true);toast('已开始处理')}else orders[selected]=JSON.parse(snapshot)}
  if(action==='write')go(order().result?'form':'result');
  if(action==='change-result')go('result');
  if(action==='camera'||action==='album'){$(`#${action==='camera'?'camera':'album'}-input`).click()}
  if(action==='evidence')openPhoto([{data:`assets/${scene().file}`,source:`巡检机器狗 ${scene().device}`,status:'原始检查照片'}],0,true);
  if(action==='undo'&&undoPhoto){branch().photos.splice(undoPhoto.index,0,undoPhoto.photo);undoPhoto=null;save();render(true)}
  if(action==='submit')submit();
});
$('#app').addEventListener('input',event=>{if(event.target.id==='material-input'){branch().text=event.target.value;event.target.removeAttribute('aria-invalid');$('#text-error').hidden=true;save()}});
$('#app').addEventListener('focusin',event=>{if(event.target.id==='material-input'){$('#app').classList.add('form-focused');$('#inline-submit').hidden=false;setTimeout(()=>event.target.scrollIntoView({block:'nearest'}),50)}});
$('#app').addEventListener('focusout',event=>{if(event.target.id==='material-input'){setTimeout(()=>{if(page==='form'&&document.activeElement?.id!=='material-input'){$('#app').classList.remove('form-focused');if($('#inline-submit'))$('#inline-submit').hidden=true}},100)}});
function fieldError(id,message){const target=$(id);target.textContent=message;target.hidden=false;return target}
function submit(){if(busy)return;const chosen=result(),value=branch();let firstError=null;if(!value.text.trim()){firstError=fieldError('#text-error',`请填写${chosen.label}`);$('#material-input').setAttribute('aria-invalid','true')}if(chosen.photo){if(!value.photos.length){const error=fieldError('#photo-error',`请至少添加 1 张${chosen.photo}`);firstError=firstError||error}else if(value.photos.some(photo=>photo.status!=='上传成功')){const error=fieldError('#photo-error','请等待当前照片全部上传成功');firstError=firstError||error}}if(firstError){firstError.scrollIntoView({block:'center'});return}const token=epoch,index=selected;busy=true;render(true);setTimeout(()=>{if(token!==epoch)return;const snapshot=JSON.stringify(orders[index]);orders[index].status='done';orders[index].completedAt=Date.now();busy=false;if(save()){go('complete');toast('提交成功')}else{orders[index]=JSON.parse(snapshot);render(true)}},1050)}
function updatePhotos(){if(page==='form'){$('#photo-list').innerHTML=photosMarkup();activateIcons()}}
function progressPhoto(photo,token){if(photo.status==='上传成功')return;setTimeout(()=>{if(token!==epoch)return;photo.status='正在上传';save();updatePhotos();setTimeout(()=>{if(token!==epoch)return;photo.status='上传成功';if(save())updatePhotos();else{photo.status='待上传';updatePhotos()}},1200)},500)}
async function readableImage(file){if(!file.type.startsWith('image/'))throw new Error('无法读取照片，请选择有效图片');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('照片读取失败，请重新选择'));reader.readAsDataURL(file)});const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('照片无法打开，请重新选择'));img.src=data});const scale=Math.min(1,1440/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.85)}
for(const kind of ['camera','album']){$(`#${kind}-input`).addEventListener('change',async event=>{const files=[...event.target.files],target=branch(),token=epoch;for(const file of files){try{const data=await readableImage(file);if(token!==epoch)return;const photo={id:`p-${Date.now()}-${Math.random()}`,data,source:kind==='camera'?'拍照':'相册',status:'待上传'};target.photos.push(photo);if(save()){updatePhotos();progressPhoto(photo,token);if($('#photo-error'))$('#photo-error').hidden=true}else{target.photos.pop();updatePhotos()}}catch(error){toast(error.message)}}event.target.value='';})}
let previewPhotos=[],previewIndex=0,previewOriginal=false;
function openPhoto(photos,index,original){previewPhotos=photos;previewIndex=index;previewOriginal=original;renderPhoto()}
function renderPhoto(){const photo=previewPhotos[previewIndex],target=$('#photo-overlay');target.innerHTML=`<div class="photo-toolbar"><button class="icon-button" data-photo-action="close" aria-label="关闭照片">${icon('arrow-left')}</button><span>${previewOriginal?'原始证据':'照片预览'} · ${previewIndex+1}/${previewPhotos.length}</span></div><div class="photo-viewport"><img src="${photo.data}" alt="${previewOriginal?'原始检查照片':'现场处理照片'}"></div><div class="photo-bottom"><span>${photo.source} · ${photo.status}</span><div class="photo-actions"><button data-photo-action="previous" aria-label="上一张" ${previewIndex===0?'disabled':''}>${icon('chevron-left')}</button><button data-photo-action="zoom">放大 / 还原</button><button data-photo-action="next" aria-label="下一张" ${previewIndex===previewPhotos.length-1?'disabled':''}>${icon('chevron-right')}</button></div></div>`;target.hidden=false;activateIcons()}
$('#photo-overlay').addEventListener('click',event=>{const action=event.target.closest('button')?.dataset.photoAction;if(action==='close')$('#photo-overlay').hidden=true;if(action==='zoom')$('.photo-viewport').classList.toggle('zoomed');if(action==='previous'&&previewIndex>0){previewIndex--;renderPhoto()}if(action==='next'&&previewIndex<previewPhotos.length-1){previewIndex++;renderPhoto()}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){if(!$('#photo-overlay').hidden)$('#photo-overlay').hidden=true;else if(mode==='screen'){$('#screen-mask').hidden=true}else if(page!=='list')back()}});
document.querySelectorAll('[data-width]').forEach(button=>button.addEventListener('click',()=>{const width=button.dataset.width;$('#device').classList.toggle('is-phone',width==='390');document.documentElement.style.setProperty('--phone-width',`${width}px`);document.documentElement.style.setProperty('--phone-height',`${width==='320'?533:730}px`);document.querySelectorAll('[data-width]').forEach(item=>item.setAttribute('aria-pressed',item===button));$('#viewport-label').textContent=`${width} × ${width==='320'?533:730} · 触屏交互`;}));
$('#font-scale').addEventListener('change',event=>{document.documentElement.style.setProperty('--font-scale',event.target.value)});
$('#reset-review').addEventListener('click',()=>{if(!confirm('恢复首屏将清除这份浏览器原型中的工单进度和所选照片，恢复三张待处理工单。是否继续？'))return;epoch++;busy=false;orders=makeOrders();tab='pending';listScroll=0;selected=0;page='list';$('#photo-overlay').hidden=true;$('#app-toast').hidden=true;save();render()});
const dispatched={};let screenScene='A02/trash';
function screenMarkup(){const item=scenes.find(value=>value.id===screenScene),sent=dispatched[item.id];return `<h2>原证据弹窗内，完成下发</h2><p class="section-intro">仅展示原检查卡片与证据弹窗局部。沿用当前组件的单栏结构、640px 宽度、滚动和关闭方式；新增内容位于卡片末行和弹窗末尾。</p><div class="screen-canvas"><div class="screen-local-head">${icon('monitor')}全空间 / 车站 · 巡检项目</div><button class="screen-check-card" id="open-evidence"><span class="screen-check-main"><span>01</span><strong>${item.check}</strong><b>异常</b></span><span class="screen-check-meta"><span>云谷路地铁站</span><span>09:38</span></span>${sent?'<div class="screen-check-sent">工单已下发</div>':''}</button><div class="screen-mask" id="screen-mask"><section class="screen-dialog" role="dialog" aria-modal="true" aria-label="巡检结果详情"><header><h3>${item.check}</h3><button id="close-evidence" aria-label="关闭详情">×</button></header><p>日常运营巡检 · 巡检机器狗 ${item.device}</p><dl><dt>检查位置</dt><dd>云谷路地铁站 · ${item.check}</dd><dt>结论</dt><dd>异常</dd><dt>到达时间</dt><dd>2026-11-11 09:38:00</dd><dt>检查/采集时间</dt><dd>2026-11-11 09:38:03</dd><dt>结果返回时间</dt><dd>2026-11-11 09:38:06</dd></dl><img src="assets/${item.file}" alt="${item.check}原始照片"><p class="source">内置巡检样图</p><dl><dt>报告标识</dt><dd>尚未取得</dd><dt>报告编号</dt><dd>—</dd></dl><article class="evidence-hazard"><strong>${item.title}</strong><p>${item.description}</p></article><div class="dispatch-section">${sent?`<dl class="dispatch-meta"><dt>工单状态</dt><dd>已下发</dd><dt>处理人</dt><dd>李明</dd><dt>下发时间</dt><dd>${fullTime(sent)}</dd></dl>`:''}<button id="dispatch" ${sent?'disabled':''}>${sent?'已下发':'下发工单'}</button></div></section></div><div class="screen-toast" id="screen-toast" role="status" hidden>下发成功</div></div><p class="section-intro">本轮预览使用独立预设内容，不读取或改写真实检查结论。下发结果仅保留在当前预览页面；手机端数据独立。</p>`}
function renderScreen(){const visible=$('#screen-mask')?!$('#screen-mask').hidden:true,scroll=$('.screen-dialog')?.scrollTop||0;$('#screen-stage').innerHTML=screenMarkup();$('#screen-mask').hidden=!visible;$('.screen-dialog').scrollTop=scroll;activateIcons();$('#open-evidence').onclick=()=>$('#screen-mask').hidden=false;$('#close-evidence').onclick=()=>$('#screen-mask').hidden=true;$('#screen-mask').onclick=event=>{if(event.target.id==='screen-mask')$('#screen-mask').hidden=true};$('#dispatch').onclick=()=>{if(dispatched[screenScene])return;dispatched[screenScene]=Date.now();renderScreen();$('.screen-dialog').scrollTop=$('.screen-dialog').scrollHeight;$('#screen-toast').hidden=false;setTimeout(()=>{if($('#screen-toast'))$('#screen-toast').hidden=true},2400)}}
function renderAssets(){$('#asset-stage').innerHTML=`<h2>12 个检查点，各自保留证据</h2><p class="section-intro">按现有设备配置、路线节点与图片绑定核对。下列为设计素材对照，独立于手机业务列表；默认列表仍为垃圾桶、消火栓、闸机三项。</p><div class="asset-grid">${scenes.map(item=>`<article class="asset-card"><img src="assets/${item.file}" alt="${item.check}检查照片"><div><small>${item.device} · 路线点 ${item.node}${item.default?'<span class="asset-default">默认启用</span>':''}</small><h3>${item.title}</h3><p>${item.location}</p><p>${item.file}</p></div></article>`).join('')}</div><p class="asset-warning">待核对：当前 A01 绑定 escalator-a02.jpg，A02 绑定 escalator-a01.jpg。此处按现有绑定展示，未修改业务代码。现有资料未给出楼层、出入口等细分位置；首版使用车站、来源设备和检查点名称。</p>`;activateIcons()}
document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(item=>item.setAttribute('aria-pressed',item===button));$('#app-stage').hidden=mode!=='app';$('#app-notes').hidden=mode!=='app';$('#screen-stage').hidden=mode!=='screen';$('#asset-stage').hidden=mode!=='assets';if(mode==='screen')renderScreen();if(mode==='assets')renderAssets()}));
window.addEventListener('pagehide',save);
render();
// 刷新后只继续本浏览器已有照片状态，不增加工单或改变结果分支。
orders.forEach(item=>Object.values(item.branches).forEach(value=>value.photos.forEach(photo=>progressPhoto(photo,epoch))));
